/// Bound text blocks without changing paragraph strings or reading positions.
fn split_text_blocks(fragments: &mut Vec<KfxFragment>, ctx: &mut ExportContext) {
    let mut refs = HashMap::new();
    let mut result = Vec::new();
    for fragment in fragments.drain(..) {
        if fragment.ftype != KfxSymbol::Content as u64 { result.push(fragment); continue; }
        let FragmentData::Ion(IonValue::Struct(fields)) = &fragment.data else { unreachable!() };
        let old_symbol = ctx.symbols.get_or_intern(&fragment.fid);
        let IonValue::List(strings) = get_field(fields, KfxSymbol::ContentList as u64).unwrap() else { unreachable!() };
        let mut chunks: Vec<Vec<IonValue>> = vec![Vec::new()];
        let mut bytes = 0;
        for (index, value) in strings.iter().enumerate() {
            let IonValue::String(text) = value else { unreachable!() };
            if bytes + text.len() > 8192 && !chunks.last().unwrap().is_empty() { chunks.push(Vec::new()); bytes = 0; }
            let chunk = chunks.len() - 1;
            let name = if chunk == 0 { fragment.fid.clone() } else { format!("{}_p{}", fragment.fid, chunk) };
            refs.insert((old_symbol, index as i64), (ctx.symbols.get_or_intern(&name), chunks[chunk].len() as i64));
            chunks[chunk].push(value.clone()); bytes += text.len();
        }
        for (index, strings) in chunks.into_iter().enumerate() {
            let name = if index == 0 { fragment.fid.clone() } else { format!("{}_p{}", fragment.fid, index) };
            let symbol = ctx.symbols.get_or_intern(&name);
            result.push(KfxFragment::new(KfxSymbol::Content, name, IonValue::Struct(vec![
                (KfxSymbol::Name as u64, IonValue::Symbol(symbol)),
                (KfxSymbol::ContentList as u64, IonValue::List(strings)),
            ])));
        }
    }
    fn rewrite(value: &mut IonValue, refs: &HashMap<(u64, i64), (u64, i64)>) {
        match value {
            IonValue::Struct(fields) => {
                let key = match (get_field(fields, KfxSymbol::Name as u64), get_field(fields, KfxSymbol::Index as u64)) {
                    (Some(IonValue::Symbol(name)), Some(IonValue::Int(index))) => Some((*name, *index)), _ => None,
                };
                if let Some((name, index)) = key.and_then(|key| refs.get(&key)).copied() {
                    for (field, value) in fields.iter_mut() {
                        if *field == KfxSymbol::Name as u64 { *value = IonValue::Symbol(name); }
                        if *field == KfxSymbol::Index as u64 { *value = IonValue::Int(index); }
                    }
                }
                for (_, value) in fields { rewrite(value, refs); }
            }
            IonValue::List(values) | IonValue::Sexp(values) => for value in values { rewrite(value, refs); },
            IonValue::Annotated(_, value) => rewrite(value, refs), _ => {},
        }
    }
    for fragment in &mut result { if let FragmentData::Ion(value) = &mut fragment.data { rewrite(value, &refs); } }
    *fragments = result;
}

